SELECT

FROM job_position p
INNER JOIN ent_company c ON c.id = p.company_id



        AND (
            p.title LIKE CONCAT('%', #{q.keyword}, '%') ESCAPE '\\'
            OR c.company_name LIKE CONCAT('%', #{q.keyword}, '%') ESCAPE '\\'
            OR c.short_name LIKE CONCAT('%', #{q.keyword}, '%') ESCAPE '\\'
        )


        AND (p.data_source IS NULL OR p.data_source = 'platform')


        AND p.data_source = #{q.source}


        AND p.tech_direction = #{q.techDirection}


        AND p.category_id = #{q.categoryId}


        AND p.city = #{q.city}


        AND p.salary_max >= #{q.salaryMin}


        AND p.salary_min <= #{q.salaryMax}


        AND p.education <= #{q.education}


        AND p.job_type = #{q.jobType}


        AND EXISTS (
            SELECT 1 FROM job_position_tag t
            WHERE t.position_id = p.id
              AND t.deleted = 0
              AND t.tag_id IN

                #{tagId}

        )




        ORDER BY p.salary_max DESC, p.id DESC


        ORDER BY p.view_count DESC, p.id DESC


        ORDER BY p.publish_time DESC, p.id DESC

SELECT t.position_id AS positionId, t.tag_id AS tagId, s.name AS tagName FROM job_position_tag t INNER JOIN skill_tag s ON s.id = t.tag_id AND s.deleted = 0 WHERE t.deleted = 0 AND t.position_id IN
#{id}
ORDER BY s.sort_no ASC, s.id ASC
